"""On-disk persistence for expenses.

The store is a single JSON file: {"schema_version": N, "expenses": [ ... ]}.

Each expense record looks like:
    {
      "id": 1,
      "date": "2024-03-04",
      "amount_usd": 42.31,          # normalized to USD at write time
      "original_amount": 39.0,      # what the user actually typed
      "original_currency": "EUR",
      "category": "food",
      "note": "groceries"
    }
"""

import json
import os
from typing import Dict, List, Optional

from tally.config import SCHEMA_VERSION
from tally.rates import normalize


def empty_store():
    return {"schema_version": SCHEMA_VERSION, "expenses": []}


def migrate(data):
    """Bring an older on-disk store up to the current schema version.

    v1 records stored a single "amount" field already in USD and a "currency"
    field naming the original currency. v2 splits that into amount_usd plus the
    original amount/currency pair.
    """
    version = data.get("schema_version", 1)
    if version == 1:
        for exp in data.get("expenses", []):
            if "amount_usd" not in exp and "amount" in exp:
                exp["amount_usd"] = exp.pop("amount")
            exp.setdefault("original_amount", exp.get("amount_usd"))
            exp.setdefault("original_currency", exp.pop("currency", "USD"))
        version = 2
    data["schema_version"] = SCHEMA_VERSION
    return data


def load(path):
    """Load the store at `path`, or return an empty store if it does not exist."""
    if not os.path.exists(path):
        return empty_store()
    with open(path, "r") as fh:
        data = json.load(fh)
    return migrate(data)


def save(path, data):
    """Write the store to `path` (pretty-printed, stable key order)."""
    directory = os.path.dirname(path)
    if directory and not os.path.isdir(directory):
        os.makedirs(directory)
    with open(path, "w") as fh:
        json.dump(data, fh, indent=2, sort_keys=True)
        fh.write("\n")


def next_id(data):
    ids = [exp.get("id", 0) for exp in data["expenses"]]
    if not ids:
        return 1
    return max(ids) + 1


def add_expense(data, date, amount, currency, category, note=""):
    """Append a new expense and return the created record.

    `amount`/`currency` are what the user supplied; the amount is normalized to
    USD before it is stored. `data` is mutated in place.
    """
    amount_usd = normalize(amount, currency)
    record = {
        "id": next_id(data),
        "date": date,
        "amount_usd": amount_usd,
        "original_amount": amount,
        "original_currency": currency.upper(),
        "category": category,
        "note": note,
    }
    data["expenses"].append(record)
    return record


def find_expense(data, expense_id):
    for exp in data["expenses"]:
        if exp.get("id") == expense_id:
            return exp
    return None


def all_expenses(data):
    return list(data["expenses"])

"""Reporting: monthly summaries, category totals, CSV export, budget checks.

Every number a report emits is in USD, because that is how amounts are stored
(see docs/requirements.md). Reports never re-convert into another currency.
"""

import csv
import io
from typing import Dict, List, Optional

from tally.config import BUDGET_WARN_RATIO, CATEGORY_BUDGETS
from tally.utils import month_key, round_money

CSV_FIELDS = ["id", "date", "category", "amount_usd", "original_amount", "original_currency", "note"]


def filter_expenses(expenses, month=None, category=None):
    """Return the expenses matching an optional month (YYYY-MM) and category."""
    result = []
    for exp in expenses:
        if month is not None and month_key(exp["date"]) != month:
            continue
        if category is not None and exp["category"] != category:
            continue
        result.append(exp)
    return result


def category_totals(expenses):
    """Return {category: total_usd} over the given expenses."""
    totals = {}
    for exp in expenses:
        cat = exp["category"]
        totals[cat] = round_money(totals.get(cat, 0.0) + exp["amount_usd"])
    return totals


def grand_total(expenses):
    """Return the total USD across the given expenses."""
    return round_money(sum(exp["amount_usd"] for exp in expenses))


def monthly_summary(expenses, month):
    """Return category totals (USD) for a single month."""
    return category_totals(filter_expenses(expenses, month=month))


def format_report(expenses, month=None, category=None):
    """Render a plain-text report of category totals to a string."""
    selected = filter_expenses(expenses, month=month, category=category)
    totals = category_totals(selected)
    lines = []
    header = "Report"
    if month:
        header += " for {}".format(month)
    if category:
        header += " (category: {})".format(category)
    lines.append(header)
    lines.append("-" * len(header))
    if not totals:
        lines.append("(no expenses)")
    else:
        for cat in sorted(totals):
            lines.append("{:<14} {:>10.2f} USD".format(cat, totals[cat]))
        lines.append("{:<14} {:>10.2f} USD".format("TOTAL", grand_total(selected)))
    return "\n".join(lines)


def format_expense_list(expenses):
    """Render individual expenses as an aligned plain-text table.

    Unlike the category report, this lists each expense on its own row. Amounts
    are shown in USD (the stored representation) with the original amount and
    currency in parentheses when they differ from USD.
    """
    if not expenses:
        return "(no expenses)"
    lines = ["{:>4}  {:<10}  {:<13}  {:>10}  {}".format("id", "date", "category", "usd", "note")]
    for exp in sorted(expenses, key=lambda e: (e["date"], e["id"])):
        origin = ""
        if exp.get("original_currency", "USD") != "USD":
            origin = "  ({:.2f} {})".format(exp["original_amount"], exp["original_currency"])
        lines.append(
            "{:>4}  {:<10}  {:<13}  {:>10.2f}  {}{}".format(
                exp["id"], exp["date"], exp["category"], exp["amount_usd"], exp.get("note", ""), origin
            )
        )
    return "\n".join(lines)


def to_csv(expenses):
    """Serialize expenses to CSV text. The amount column is amount_usd."""
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=CSV_FIELDS)
    writer.writeheader()
    for exp in expenses:
        row = {field: exp.get(field, "") for field in CSV_FIELDS}
        writer.writerow(row)
    return buffer.getvalue()


def overall_stats(expenses):
    """Return summary statistics (all USD) across the given expenses.

    Keys: count, total, average, first_date, last_date. Empty input yields
    zeros and None dates rather than raising.
    """
    if not expenses:
        return {"count": 0, "total": 0.0, "average": 0.0, "first_date": None, "last_date": None}
    dates = sorted(exp["date"] for exp in expenses)
    total = grand_total(expenses)
    return {
        "count": len(expenses),
        "total": total,
        "average": round_money(total / len(expenses)),
        "first_date": dates[0],
        "last_date": dates[-1],
    }


def budget_status(expenses, month):
    """Compare a month's category spending against CATEGORY_BUDGETS.

    Returns a list of dicts, one per budgeted category:
        {category, spent, budget, ratio, state}
    where state is "ok", "warn" (>= BUDGET_WARN_RATIO) or "over" (> budget).
    """
    spent = monthly_summary(expenses, month)
    rows = []
    for cat in sorted(CATEGORY_BUDGETS):
        budget = CATEGORY_BUDGETS[cat]
        used = spent.get(cat, 0.0)
        ratio = (used / budget) if budget else 0.0
        if used > budget:
            state = "over"
        elif ratio >= BUDGET_WARN_RATIO:
            state = "warn"
        else:
            state = "ok"
        rows.append(
            {
                "category": cat,
                "spent": round_money(used),
                "budget": budget,
                "ratio": ratio,
                "state": state,
            }
        )
    return rows

"""Currency conversion.

Every amount that enters the store is normalized to USD (see docs/requirements.md).
`RATES` maps a currency code to the number of USD one unit is worth. The rates are
treated as fixed constants: several tests pin totals computed from them.
"""

from tally.config import DEFAULT_CURRENCY

# 1 unit of <currency> is worth RATES[<currency>] USD.
RATES = {
    "USD": 1.0,
    "EUR": 1.08,
    "GBP": 1.27,
    "SGD": 0.74,
    "JPY": 0.0067,
    "INR": 0.012,
}


def supported_currencies():
    """Return the sorted list of currency codes we can convert."""
    return sorted(RATES.keys())


def to_usd(amount, currency):
    """Convert `amount` given in `currency` to USD.

    The currency code is matched case-insensitively. Unknown codes raise
    ValueError so a typo never silently produces a wrong number.
    """
    code = currency.upper()
    if code not in RATES:
        raise ValueError(
            "unsupported currency {!r}; known: {}".format(
                currency, ", ".join(supported_currencies())
            )
        )
    return round(amount * RATES[code], 2)


def normalize(amount, currency):
    """Normalize an amount in `currency` into USD, the stored representation."""
    return to_usd(amount, currency)


def is_default_currency(currency):
    return currency.upper() == DEFAULT_CURRENCY

